-- EKB full M10.5 closure retrospective: all new actionable findings, preserving 17 historical entries.
-- Sole DB mutation: public.lf_error_knowledge, through ACTUALIZACION_DB_LF / Migration Train.
-- Evidence readback: work_item 477 DONE 6/6, two genuine canonical assertion receipts.
DO $m105_ekb$
DECLARE
 v_batch jsonb := $ekbdata$[{"code":"IG-M105-PASS-FUNCIONAL-NO-CIERRE-019","category":"ENGINEERING_ORCHESTRATION","severity":"HIGH","phase":"EXECUTION","state":"VALIDATED_TESTED","pr":"2668;2694;2695;2698;2705;2709","title":"Una muestra PASS no incrementa el ledger mientras falta el recibo y la transicion","description":"M10.5 permanecio dos dias en 15% y CP2 PENDING a pesar de ONB_001 run 931 PASS_CP2_MUESTRA, cinco validadores y 14/14 pruebas de jueces. Los merges de infraestructura candidata no constituyeron checkpoint DONE. El progreso oficial salto 15->75->100 solo despues de transiciones canonicas con prueba y readback.","root":"Se confundio preparacion/registro de una operacion transversal candidata con ejecucion del checkpoint material. El cierre quedo acoplado a terminar una capacidad generica aun no autorizada, aunque ya existia la ruta de migracion gobernada ACTUALIZACION_DB_LF.","pattern":"PASS_MUESTRAL_Y_PR_MERGED_PERO_LEDGER_PENDING","prevention":"Tras un PASS funcional leer status, assertion_receipt_sha256 y bootstrap. Elegir ruta de escritura YA autorizada para el deliverable exacto (Train/ACTUALIZACION_DB_LF), no activar una operacion transversal solo para cerrar una unidad. Actualizar porcentaje exclusivamente desde engineering_work_checkpoints.","validation":"PR2705 Train segunda corrida 38648171863 aplico CP2/CP3/CP4: 75%. PR2709 Train 38648806785 aplico CP5/CP6: 100%, bootstrap STOP_TERMINAL_DONE; los PR 2668/2694/2695/2698 solo materializaron infraestructura candidata sin progreso de la unidad.","source":"supabase://programacion.engineering_work_checkpoints/477;github://cristhianlujan/claude-persona-lf-patch/pull/2705"},{"code":"IG-M105-SOURCEPACK-13-VS-ACTION-SPEC-MUESTRA-020","category":"GOVERNANCE","severity":"HIGH","phase":"PREFLIGHT","state":"VALIDATED_TESTED","pr":"2705;2709","title":"SOURCE_PACK historico de 13 pantallas contradijo criterios actuales de muestra","description":"Despues de reformar CP2 a una pantalla y cinco familias, el source_pack_v1.checkpoint_inputs de CP3/CP4/CP5/CP6 aun contenia SELECT historicos con count=13 y run_ids 13. Los action_specs_v1 vigentes exponian consultas exactas de ONB_001. Ejecutar las consultas heredadas hubiera producido falsos FAIL sin un error del sistema.","root":"La migracion de alcance corrigio el contrato ejecutivo y sus verification_queries, pero no reconcilio de modo simultaneo la documentacion de lecturas historicas; coexistian dos proyecciones distintas de la misma unidad.","pattern":"SOURCE_PACK_LEGADO_FALSO_FAIL_CON_ACTION_SPEC_VIGENTE","prevention":"Antes de ejecutar cada checkpoint obtener action_spec V3 de la unidad y su verification_query vigente; comprobar semantica y currentness contra EKB. Source_pack historico sirve como contexto, NO debe introducir nuevamente 13 pantallas/47 familias. Actualizar o marcar obsoletas las consultas legadas en mantenimiento planificado, sin mutar dependencias ni ampliar alcance por accidente.","validation":"En read-only las consultas action_spec CP3=M7 PASS y CP4=M8 PASS; CP5 readback de stale PASS, CP6 FAIL solo por predecesores PENDING. Finalmente las migraciones 20261014222831 y 20261014223836 cerraron 6/6 sin exigir censo de 13.","source":"supabase://programacion.engineering_plan_units/IG_CURATOR_VALIDATOR_REFACTOR_V2/M10.5;github://cristhianlujan/claude-persona-lf-patch/pull/2705"},{"code":"IG-M105-CP2-MATERIAL-ASSERTION-ROLLBACK-021","category":"ENGINEERING_VALIDATION","severity":"HIGH","phase":"EXECUTION","state":"VALIDATED_TESTED","pr":"2705","title":"Cerrar CP2 material exige recibo, negativo 4/5, rollback y readback canónico","description":"La evidencia actual del run 931 cumplio PASS_CP2_MUESTRA (1 pantalla, 5 familias con SHA/identidades) y rechazo de run 825 obsoleto. Antes del DONE se sometio observacion falsa 4/5 al registrador y se exigio ENGINEERING_ASSERTION_RESULT_FAILED. Luego se ejecuto el cierre real CP2-CP4 en subtransaccion con PZ088 y rollback comprobado, seguido de segunda ejecucion definitiva.","root":"Los intentos anteriores no conectaban el PASS de validador con el recibo estructurado y guard del checkpoint; agregar jueces genericos por si solo no materializa un assertion_receipt del CP.","pattern":"CP_MATERIAL_PASS_SIN_SHA_DE_ASERCION_Y_ROLLBACK","prevention":"Derivar observed del proveedor canónico y del pass_when actual, no del cliente. Probar negativo con 4/5, exigir cero residuo; registrar con fn_engineering_checkpoint_assertion_record_v1, verificar digest contractual/recibo y pasar por fn_engineering_checkpoint_transition_v1. Primero ensayo reversible, despues commit via Train; nunca deshabilitar fn_guard_engineering_material_checkpoint_done_v1.","validation":"PR2705 migracion 20261014222831; CP2 NEW_RUNS_VNEXT DONE, assertion_contract_sha256=ad6b07b672659b258fa3df43005328069755001997768ff6fc55dcee04a8cab1 y assertion_receipt_sha256=787c3c807cead4c82021c210a24223e72950f0a6d727e4b9fb59a578e7a63543; CP3/CP4 DONE; ledger 75%.","source":"supabase://programacion.engineering_work_checkpoints/477/NEW_RUNS_VNEXT;github://cristhianlujan/claude-persona-lf-patch/pull/2705"},{"code":"IG-M105-CP3-CP4-READBACK-SIN-MATERIALIDAD-022","category":"ENGINEERING_VALIDATION","severity":"MEDIUM","phase":"EXECUTION","state":"VALIDATED_TESTED","pr":"2705","title":"M7 y M8 son READBACK_ONCE; no heredan el cierre material de CP2","description":"CP3 SUITE_M7_GREEN y CP4 PERF_M8_GREEN estaban PENDING aunque sus verification_queries vigentes devolvian PASS. CP3 comprobo cinco familias y tres observaciones semanticas (algunas production_ready BLOCKED son decisiones de evaluacion, no errores tecnicos). CP4 observo validator_elapsed_ms=120015 con budget=150000 y SUMMARY PUBLISHED.","root":"Un flujo unico de cierre quiso exigir el mismo registrador material a checkpoints cuya naturaleza contractual es READBACK_ONCE y requires_material_execution=false.","pattern":"READBACK_NO_MATERIAL_TRATADO_COMO_RUN_TEST","prevention":"Por checkpoint consultar action_kind y requires_material_execution. Para READBACK_ONCE efectuar su query exacta una vez, exigir PASS y evidencia identificable, y transicionar usando el ledger canónico en secuencia; no fabricar assertion_receipt material ni reejecutar pantallas cuando el resultado actual no derivo.","validation":"Read-only CP3 y CP4 PASS; PR2705 migracion 20261014222831 transiciono ambos a DONE, evidencia run931/M7 PASS y M8=120015ms, M10.5 paso 15 a 75%.","source":"supabase://programacion.v_ig_m105_cp2_sample_readback_v1;github://cristhianlujan/claude-persona-lf-patch/pull/2705"},{"code":"IG-M105-CP5-NEGATIVO-REAL-VS-FIXTURE-023","category":"ENGINEERING_VALIDATION","severity":"HIGH","phase":"EXECUTION","state":"VALIDATED_TESTED","pr":"2709","title":"Un negativo stale requiere rechazo ejecutado sobre oraculo actual, no fixture","description":"El archivo neg_stale_run.py existente demostraba predicados locales pero advertia que no acredita cierre material. La vista ya mostraba stale_negative_verified=true; eso tampoco certifica la prueba adversarial del checkpoint. La migracion final invoco fn_input_readiness_run_is_current sobre run 825 (false) y 931 (true), contrasto fn_input_run_is_source_current y ejercito rechazo de admision PZ089, sin alterar los runs.","root":"Confundir la observacion read-only de runs obsoletos o la suite local con la prueba negativa operacional que exige action_kind=BOUNDED_CHECKPOINT_TEST_AUTHORING y un assertion_receipt real.","pattern":"FIXTURE_NEGATIVA_SUSTITUYE_PRUEBA_REAL_CP","prevention":"Usar dos run IDs canónicos distintos y vigentes para el test (stale y current), identidad de pantalla y snapshots diferenciados. Ejecutar el predicado real de currentness, rechazar el stale con motivo identificable, verificar rollback, hacer negativo de assertion recorder con adversarial_case_executed=false y solo luego registrar observed/test_exit_code y DONE.","validation":"PR2709 run Train 38648806785; migracion 20261014223836; CP5 NEG_STALE_RUN DONE; assertion_contract_sha256=37f7d6f434512bfd61abca75dd8d105597ab5934611bb1f1f2f594daa4fd5379; assertion_receipt_sha256=38b28ea8cfcd09e455268099f2eb48d8ef001f3673633d017adb802e6995fd9d. Run825=REJECTED, run931=CURRENT.","source":"supabase://programacion.engineering_work_checkpoints/477/NEG_STALE_RUN;github://cristhianlujan/claude-persona-lf-patch/pull/2709"},{"code":"IG-M105-CP6-E2E-TERMINAL-SIN-PRODUCCION-024","category":"ENGINEERING_ORCHESTRATION","severity":"HIGH","phase":"CLOSURE","state":"VALIDATED_TESTED","pr":"2709","title":"CP6 exige cuatro anteriores DONE y termina unidad; muestra no habilita produccion","description":"E2E_READBACK devolvia FAIL mientras CP2-CP5 no estaban oficialmente DONE, aunque ONB_001 tenia PASS. Despues del cierre de CP5, el readback exigio los cuatro checkpoints, run931 fuente actual, cinco familias, no produccion; CP6 transiciono a DONE y el bootstrap devolvio STOP_TERMINAL_DONE.","root":"Se confundio PASS de muestra con estado terminal de la unidad, y la logica de next_checkpoint podia fallar al cerrar la ultima etapa sin sucesor.","pattern":"READBACK_FINAL_PASO_SIN_UPSTREAM_DONE_O_CON_PROMOCION_IMPLICITA","prevention":"CP6 requiere estado canónico de CP2 CP3 CP4 CP5 y sample_verdict actual; no aceptar promesa de cierre. El ultimo paso no tiene next_checkpoint: admitir exclusivamente terminal STOP_TERMINAL_DONE con 100%, work DONE y 6/6. Separar evaluacion muestral de autorizacion de produccion en todos los recibos.","validation":"PR2709 migracion 20261014223836; M10.5 work_item 477 DONE, 6/6 DONE, progress=100, terminal_action=STOP_TERMINAL_DONE, authorizes_production=false. Commit main 830146b8e8a695ba36835a5ae1e1508b57e862db.","source":"supabase://programacion.fn_engineering_unit_bootstrap_v3/IG_CURATOR_VALIDATOR_REFACTOR_V2/M10.5;github://cristhianlujan/claude-persona-lf-patch/pull/2709"},{"code":"IG-M105-TRAIN-JSONB-PRECEDENCIA-42883-025","category":"CI_CD_GOVERNANCE","severity":"HIGH","phase":"IMPLEMENTATION","state":"VALIDATED_TESTED","pr":"2705","title":"Precedencia SQL JSONB provoco 42883 en Train pese a que el preflight paso","description":"Primera corrida PR2705 Train 38647704224 fallo EXACT_APPLY_FALLBACK_FAILED antes del ledger con PostgreSQL 42883 operator does not exist: boolean -> unknown, LINE (v_observed @> v_contract->'pass_when') IS DISTINCT FROM true. La expresion no tenia parentesis en la extraccion JSONB del segundo argumento. GitHub Train marco APPLIED=false, elimino ready-to-merge y dejo el checkpoint en 15%.","root":"El control superficial de SQL verifico presencia de operadores pero no parseo la precedencia real: @> y -> interactuaron sin parentesis. No era fallo de Router ni de evaluacion ONB_001.","pattern":"OPERADOR_JSONB_AMBIGUO_EN_SQL_PREAPPLY","prevention":"En comparaciones JSONB usar siempre (v_observed @> (v_contract->'pass_when')) IS DISTINCT FROM true. Antes de reenvio validar SQL real (idealmente PostgreSQL de staging o rollback), inspeccionar ERROR y SQLSTATE de logs Train, editar solo el blob del PR y reetiquetar tras clasificacion. No cambiar guardas ni saltar Train.","validation":"Run 38647704224 fallo antes de ledger; PR2705 patch 5739600edde794527c5fc0672c6662be6ff27f70 sustituyo una expresion; segunda corrida 38648171863 SUCCESS, migracion 20261014222831 aplicada y CP2-CP4 DONE.","source":"github://cristhianlujan/claude-persona-lf-patch/actions/runs/38647704224;github://cristhianlujan/claude-persona-lf-patch/pull/2705"},{"code":"ENGINEERING-CP-OPERACION-CANDIDATA-NO-DEPENDENCIA-026","category":"ENGINEERING_GOVERNANCE","severity":"HIGH","phase":"GOVERNANCE","state":"VALIDATED_TESTED","pr":"2657;2668;2694;2695;2698;2705;2709","title":"Operación candidata con jueces no debe bloquear cierre por ruta DB ya autorizada","description":"La operacion generica CIERRE_CHECKPOINT_INGENIERIA_LF se instalo con PR2668, registro con procedencia autentica PR2694 y adquirio 6/6 contratos de paso, jueces y bindings por PR2695/2698. La operacion siguio CANDIDATO_READ_ONLY, OP_CANDIDATE y Router CHECKPOINT_CLOSE write_allowed=false; no tenia calificacion. El cierre M10.5 pudo usar ACTUALIZACION_DB_LF / MIGRATION UPDATE/Train ya ACTIVE sin promover la candidata.","root":"Se elevo un componente reutilizable futuro a dependencia obligatoria del checkpoint actual pese a existir otra via gobernada y probada; prolongaba el proyecto sin cambiar ledger.","pattern":"ACTIVAR_OPERACION_GENERICA_CANDIDATA_COMO_GATE_DE_CP_EXISTENTE","prevention":"Separar 'infraestructura candidata a reutilizar' de 'cierre puntual autorizado'. Para checkpoint exacto usar la ruta ACT-0001 ya activa y el par recorder/transition, con pruebas y ledger. Mantener CIERRE_CHECKPOINT_INGENIERIA_LF sin permisos hasta su propia suite, qualification, identity, provider y Router downstream consumer; NUNCA activar ni conceder grants como atajo.","validation":"Readback final: CIERRE_CHECKPOINT_INGENIERIA_LF CANDIDATO_READ_ONLY, Router write_allowed=false, 6 jueces vinculados, M10.5 DONE 100% por migraciones PR2705 y PR2709. Las 14 pruebas de jueces validaron codigo puro, NO runtime/operacion promovida.","source":"supabase://public.lf_operation_registry/CIERRE_CHECKPOINT_INGENIERIA_LF;github://cristhianlujan/claude-persona-lf-patch/pull/2698"},{"code":"ENGINEERING-CP-JUECES-IDENTIDAD-TERMINAL-027","category":"ENGINEERING_VALIDATION","severity":"HIGH","phase":"CONSTRUCTION","state":"VALIDATED_TESTED","pr":"2695;2698","title":"Cada juez aislado debe comprobar identidad y aceptar ultimo checkpoint terminal","description":"En borrador PR2695, runtime_authenticated=true era obligatorio solo en init_execution y los otros cinco jueces podian invocarse aisladamente sin esa condicion. Se corrigio el preflight comun para exigir runtime_authenticated, owner_role=SUPER_ADMIN y release_promotion_requested=false en todos; se retiro el skip del negativo y se cubrio ultimo checkpoint sin next_checkpoint con STOP_TERMINAL_DONE. El codigo exacto paso 14/14 pruebas Python.","root":"Se asumio ejecucion secuencial y herencia de validacion del primer paso para jueces reutilizables que son invocables individualmente; tambien se asumio un sucesor para toda transicion, incluso terminal.","pattern":"JUEZ_INDEPENDIENTE_HEREDA_IDENTIDAD_Y_EXIGE_NEXT_TERMINAL","prevention":"Cada minijuez siempre valida contexto canonico, identidad y scope en su propia entrada. Negativos de identidad, owner y prohibicion de promocion deben afectar los seis. Readback final permite next_checkpoint=null solo si unit_terminal=true y next_terminal_action=STOP_TERMINAL_DONE. Conservar algoritmo como verificador puro: el runner obtiene identidad, no el usuario.","validation":"PR2695 merged main 944285b2d7be0c2b6b677430dd14ec9c5c865e8d; codigo hash SHA256 8000f82c1d95ce9c7fa13bbcfae1d1a01b296cbb5aa8041f94fac8e308eda8bb; 14/14 unittest PASS. PR2698 ledger 20261014221000 con 6 pasos/contratos/jueces/bindings; write_allowed=false.","source":"github://cristhianlujan/claude-persona-lf-patch/pull/2695;github://cristhianlujan/claude-persona-lf-patch/pull/2698"},{"code":"ENGINEERING-CP-SECURITY-CONTEXT-NO-EXPLICITO-028","category":"SECURITY_GOVERNANCE","severity":"MEDIUM","phase":"PUBLISH","state":"VALIDATED_TESTED","pr":"2668;2694;2695","title":"Bloqueo generico de herramienta no prueba vulnerabilidad de agente LF","description":"La publicacion inicial de migracion de alta en GitHub fue rechazada dos veces por un control de seguridad de OpenAI sin codigo HTTP ni razon especifica. No hubo evidencia de SQL peligroso o vulnerabilidad concreta. Se documento en PR2668 que la operacion es interna, con Router, scope de checkpoint, autenticacion, recibos, efectos acotados, candidato no activo, sin EXECUTE y sin alterar Train. Un intento posterior por la misma herramienta autorizada logro publicar el alta del candidato.","root":"La señal de seguridad de herramienta era inespecifica y fue interpretada como si demostrara un defecto de seguridad del diseño, sin disponer de la regla activada.","pattern":"CONTROL_DE_HERRAMIENTA_INESPECIFICO_CONFUNDIDO_CON_FALLO_DEL_SISTEMA","prevention":"Ante bloqueos no inferir causa ni eludir controles cambiando rutas. Publicar contexto de finalidad legitima y privilegio minimo en PR; pedir revision autorizada cuando persista. Mantener separadas admision de herramienta, gobernanza Router y seguridad real. No prometer que una justificacion obligara a aceptar.","validation":"Contexto publicado en PR2668; posterior create_file por mismo conector permitido y PR2694 merger por Train; operacion CANDIDATO_READ_ONLY/Router write_allowed=false. La causa interna del filtro OpenAI permanece no revelada; no afirmar false positive confirmado.","source":"github://cristhianlujan/claude-persona-lf-patch/pull/2668;github://cristhianlujan/claude-persona-lf-patch/pull/2694"},{"code":"ENGINEERING-CP-GITHUB-FILE-PREEXISTS-422-029","category":"CI_CD_GOVERNANCE","severity":"MEDIUM","phase":"CONSTRUCTION","state":"VALIDATED_TESTED","pr":"2709","title":"GitHub create_file sobre test CP5 preexistente devolvio 422 por SHA ausente","description":"Al iniciar CP5 se intento crear neg_stale_run.py con create_file y GitHub devolvio 422 Invalid request: sha wasn't supplied. El archivo ya existia en main y contenia comprobador local con advertencia de que no cerraba el checkpoint por si solo.","root":"No se verifico existencia y contenido del target antes de elegir create_file vs update_file, aunque action_spec declaraba EXACT_NEW_OR_UPDATE_FILE.","pattern":"CREATE_FILE_EXISTENTE_SIN_BLOB_SHA","prevention":"En cada target Git autorizado primero fetch_file sobre main/rama. Si existe, inspeccionar valor y decidir reutilizarlo o update_file con content_sha exacto; si no, create_file. No duplicar el artifact por otro nombre ni reescribir la prueba local para simular autoridad; preferir reutilizar el oraculo SQL canónico cuando corresponda.","validation":"El target preexistente Git blob SHA 53f8470b68029846e252a0eafdbd2c3595ba9d18 se conservo; PR2709 uso fn_input_readiness_run_is_current real y cerro CP5/CP6 sin modificar neg_stale_run.py.","source":"github://cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/engineering_checkpoints/m10_5/neg_stale_run.py"},{"code":"IG-M105-HISTORICO-EKB-001-018-SCOPE-030","category":"KNOWLEDGE_GOVERNANCE","severity":"HIGH","phase":"RECONCILIATION","state":"VALIDATED_TESTED","pr":"2705;2709","title":"Los EKB 001-018 son historia verificada; no reintroducen gates de release o 13 pantallas","description":"Antes del cierre ya existian 17 entradas IG-M105-* y un EKB transversal ENGINEERING-CHECKPOINT-CLOSURE-PROVENANCE-PREWRITE-002. Incluyen fallos historicos de cutover release, Edge/OIDC/13 pantallas, R17, producer, semantica y autorizacion. No debian borrarse ni rehacerse; varias describen un alcance historico diferente al contrato actual de muestra ONB_001. El cierre 100% fue un deliverable de evaluacion muestral, NO certificacion Edge post-cutover de 13 pantallas ni despliegue operativo.","root":"Se trato evidencia historica y gates de procedimientos distintos como requisitos permanentes del checkpoint vigente, prolongando investigacion y repeticion de pruebas sin nuevo valor.","pattern":"APRENDIZAJE_HISTORICO_SE_REUSA_COMO_CONTRATO_ACTUAL_OBSOLETO","prevention":"Leer todos los EKB relacionados, preservarlos como historico. Comparar el requisito de cada entrada contra el action_spec vigente y su naturaleza; no reinterpretar 'historico 13-screen' como una obligacion actual ni borrar deuda tecnica Edge/R17. Registrar resolucion concreta con PR/ledger/readback sin modificar datos pasados.","validation":"Supabase tenia 17 registros IG-M105 antes de este lote. Action spec CP2 pass_when=1 pantalla/5 familias/no_production, M10.5 6/6 DONE y STOP_TERMINAL_DONE; operacion Edge deploy no activada por este cierre; migraciones 20261014222831 y 20261014223836.","source":"supabase://public.lf_error_knowledge/IG-M105;supabase://programacion.engineering_plan_units/IG_CURATOR_VALIDATOR_REFACTOR_V2/M10.5"},{"code":"ENGINEERING-CP-TRAIN-SQL-SINTAXIS-42601-031","category":"CI_CD_GOVERNANCE","severity":"MEDIUM","phase":"IMPLEMENTATION","state":"VALIDATED_TESTED","pr":"2668","title":"Regex SHA SQL sin cierre produjeron 42601 antes de instalar operacion candidata","description":"Durante la instalacion inicial del candidato de cierre de checkpoint se enviaron expresiones regex SHA truncadas, faltando el cierre del patron ^[a-f0-9]{64}$ y comillas, causando error PostgreSQL 42601. Se repararon fuente y migracion en el PR2668 antes de pasar Train; los controles de 64 hex se conservaron.","root":"El artefacto candidato SQL no recibio revision de sintaxis y quoted-regex completa antes de enviar a Train; no era error de seguridad ni motivo para relajar validadores.","pattern":"PATRON_REGEX_SQL_TRUNCADO_PREAPPLY_42601","prevention":"Para cada regex de SHA validar delimitador, cuantificador, ancla $, quote y compilacion en PostgreSQL antes de etiquetar; mantener tests negativos para digest corrupto. Si Train aborta, corregir blob exacto, no tocar gobernanza transversal ni omitir el predicado.","validation":"PR2668 merged 84c35b9abce10ef84e7d9f2f41f19da0d370f5ec; migracion 20261014200751 aplicada, funciones candidatas instaladas, ningun privilegio EXECUTE a anon/authenticated/service_role.","source":"github://cristhianlujan/claude-persona-lf-patch/pull/2668"},{"code":"IG-M105-TRAIN-ATOMICO-GIT-LEDGER-DB-032","category":"CI_CD_GOVERNANCE","severity":"HIGH","phase":"CLOSURE","state":"VALIDATED_TESTED","pr":"2705;2709","title":"Train preapply fallo sin DONE falso; segundo cierre verifico Main-ledger-DB","description":"El PR2705 fallo en primer apply SQL 42883 antes de ledger: progreso real permanecio 15%, sin transiciones parciales. Corregido el blob, Train aplico CP2-CP4 con rollback previo y readback 75%. El PR2709 exigio prueba negativa real, rollback de CP5-CP6, luego readback 100%. Ambos merges llegaron a main sin activar la operacion candidata.","root":"Declarar avance por etiqueta, checks o PR sin reconciliar commit, ledger y DB; una migracion SQL compleja puede fallar aun cuando PASE admita fuente.","pattern":"MERGED_O_CHECK_GREEN_NO_IGUAL_A_APPLIED_Y_DONE","prevention":"Cadena obligatoria PR->PASE->Train exact migration->ledger->merge main->readback material: status por checkpoint, recibos, terminal, ausencia de promocion. Ante PRE_APPLY_FAILED, no inventar progreso; reparar solo causa puntual y reintentar despues de clasificacion y verificacion real. Mantener pruebas de rechazo + rollback con cero residuo.","validation":"PR2705 merged 9f833769f87b40a78b0d1549e6d3cde0b1228c09; ledger 20261014222831. PR2709 merged 830146b8e8a695ba36835a5ae1e1508b57e862db; ledger 20261014223836. Supabase work_item 477 DONE, 6/6, progress 100, 2 material receipts y production=false.","source":"github://cristhianlujan/claude-persona-lf-patch/pull/2705;github://cristhianlujan/claude-persona-lf-patch/pull/2709"}]$ekbdata$::jsonb;
 v_item jsonb;
 v_code text;
 v_count integer;
 v_test constant text := 'IG-M105-EKB-ROLLBACK-PROBE-20261014';
BEGIN
 IF (SELECT status FROM programacion.engineering_work_items WHERE id=477) IS DISTINCT FROM 'DONE'
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints WHERE work_item_id=477 AND status='DONE')<>6
 OR (SELECT coalesce(sum(weight::numeric),0) FROM programacion.engineering_work_checkpoints WHERE work_item_id=477 AND status='DONE')<>100
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints WHERE work_item_id=477
     AND checkpoint_code IN ('NEW_RUNS_VNEXT','NEG_STALE_RUN')
     AND assertion_receipt_sha256 ~ '^[0-9a-f]{64}$'
     AND assertion_receipt->>'passed'='true'
     AND assertion_contract_sha256=assertion_receipt->>'contract_sha256')<>2
 OR (SELECT count(*) FROM supabase_migrations.schema_migrations
     WHERE name IN ('lf_ig_m105_cp2_cp4_canonical_closure_v1',
       'lf_ig_m105_cp5_cp6_stale_negative_real_closeout_v1'))<>2
 OR (SELECT sample_verdict FROM programacion.v_ig_m105_cp2_sample_readback_v1) IS DISTINCT FROM 'PASS_CP2_MUESTRA'
 OR (SELECT authorizes_production FROM programacion.v_ig_m105_cp2_sample_readback_v1) IS DISTINCT FROM false
 OR (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo LIKE 'IG-M105-%')<17
 OR (SELECT status FROM public.lf_operation_registry
     WHERE operation_code='CIERRE_CHECKPOINT_INGENIERIA_LF') IS DISTINCT FROM 'CANDIDATO_READ_ONLY'
 OR (SELECT write_allowed FROM public.lf_router_action_registry
     WHERE operation_code='CIERRE_CHECKPOINT_INGENIERIA_LF'
       AND asset_type='ENGINEERING_CHECKPOINT') IS DISTINCT FROM false
 THEN RAISE EXCEPTION 'M105_EKB_AUTHORITY_PRECONDITION_NOT_MET'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(v_batch)) <> 14
 OR (SELECT count(DISTINCT item->>'code') FROM jsonb_array_elements(v_batch) item) <> 14
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_batch) item
  JOIN public.lf_error_knowledge e ON e.codigo=item->>'code')
 THEN RAISE EXCEPTION 'M105_EKB_DUPLICATE_OR_BATCH_DRIFT'; END IF;
 -- PostgreSQL rollback proof using the real target and a marker not kept.
 BEGIN
  INSERT INTO public.lf_error_knowledge
    (id,codigo,categoria,titulo,estado,created_at,updated_at)
  VALUES(gen_random_uuid(),v_test,'ENGINEERING_ORCHESTRATION','EKB reversible insert test',
       'TEST_PROBE',now(),now());
  RAISE EXCEPTION 'M105_EKB_ROLLBACK_SENTINEL' USING ERRCODE='PZ092';
 EXCEPTION WHEN SQLSTATE 'PZ092' THEN NULL;
 END;
 IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo=v_test)
 THEN RAISE EXCEPTION 'M105_EKB_ROLLBACK_LEFT_RESIDUE'; END IF;

 FOR v_item IN SELECT value FROM jsonb_array_elements(v_batch) LOOP
  v_code := v_item->>'code';
  IF v_code IS NULL OR btrim(v_code)='' OR v_item->>'root' IS NULL
  OR v_item->>'prevention' IS NULL OR v_item->>'validation' IS NULL
  OR v_item->>'description' IS NULL OR v_item->>'source' IS NULL
  THEN RAISE EXCEPTION 'M105_EKB_UNDERDOCUMENTED:%',v_code; END IF;
  INSERT INTO public.lf_error_knowledge
    (id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,
     severidad,frecuencia,primera_vez,ultima_vez,lote_origen,pr,estado,evidencia,
     created_at,updated_at,lifecycle_phase,consumer_role,root_cause_family,
     detectability,source_context,source_ref)
  VALUES
    (gen_random_uuid(),v_code,v_item->>'category',v_item->>'title',
     v_item->>'description',v_item->>'root',v_item->>'pattern',
     v_item->>'prevention',v_item->>'validation',v_item->>'severity',1,
     now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2',v_item->>'pr',
     v_item->>'state',v_item->>'validation',
     now(),now(),v_item->>'phase',
     ARRAY['ENGINEERING_EXECUTOR','VALIDATOR','ARCHITECT']::text[],
     CASE WHEN (v_item->>'category') IN ('ENGINEERING_ORCHESTRATION','ENGINEERING_GOVERNANCE','KNOWLEDGE_GOVERNANCE')
       THEN 'R5_EROSION_PROCESO' ELSE 'R2_NO_VE' END,
     'PROCESS_DEPENDENT',
     'M10.5 PAULO-164, 2026-10-13/14: retrospective de todas las corridas, sin promocion de produccion',
     v_item->>'source');
 END LOOP;
 SELECT count(*) INTO v_count FROM public.lf_error_knowledge e
 JOIN LATERAL jsonb_array_elements(v_batch) entry ON e.codigo=entry.value->>'code';
 IF v_count<>14 OR
  (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo=v_test)<>0
 THEN RAISE EXCEPTION 'M105_EKB_POSTWRITE_READBACK_FAILED:%',v_count; END IF;
END $m105_ekb$;
